import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"Compatibility","description":"Mobile Inspector development documentation · Compatibility","frontmatter":{"title":"Compatibility","description":"Mobile Inspector development documentation · Compatibility"},"headers":[],"relativePath":"en/guide/compatibility.md","filePath":"en/guide/compatibility.md"}'),o={name:"en/guide/compatibility.md"};function d(n,t,s,l,c,p){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><p>Compatibility describes source requirements, not a promise of every operating-system/device combination. Match the CLI, SDK and v1 event contract from one reviewed source selection.</p><h2 id="compatibility-matrix" tabindex="-1">Compatibility matrix <a class="header-anchor" href="#compatibility-matrix" aria-label="Permalink to &quot;Compatibility matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Requirement</th><th>Status</th></tr></thead><tbody><tr><td>CLI / viewer / MCP</td><td>Node.js 22+; OpenSSL for generated TLS</td><td>development</td></tr><tr><td>JavaScript / H5</td><td>ESM; secure camera context; trusted HTTPS ingestion</td><td>source</td></tr><tr><td>WeChat</td><td>host adapter; legal domains; trusted HTTPS</td><td>source</td></tr><tr><td>iOS</td><td>iOS 15+; local Swift package</td><td>source</td></tr><tr><td>Android</td><td>Kotlin 2.1.20; JVM 17; OkHttp 4.12</td><td>source</td></tr><tr><td>HarmonyOS</td><td>ArkTS; system-trusted HTTPS; API24 host compilation separate</td><td>source</td></tr><tr><td>Codex diagnosis</td><td>UNSUPPORTED_SANDBOX</td><td>unavailable</td></tr><tr><td>Responses diagnosis</td><td>strict no-tools adapter</td><td>source-only; compatibility unaccepted</td></tr><tr><td>M4 repair</td><td>not implemented</td><td>unavailable</td></tr></tbody></table><h2 id="trust-differs-by-platform" tabindex="-1">Trust differs by platform <a class="header-anchor" href="#trust-differs-by-platform" aria-label="Permalink to &quot;Trust differs by platform&quot;">​</a></h2><p>H5, WeChat and HarmonyOS require system-trusted HTTPS for ingestion. A self-signed desktop certificate is not enough. H5 scanning also needs a secure camera context; WeChat requires its platform domain configuration. Native iOS and Android have a separate diagnostic leaf-pinning transport that preserves normal hostname and validity checks. None of these settings changes business TLS.</p><h2 id="verification-levels" tabindex="-1">Verification levels <a class="header-anchor" href="#verification-levels" aria-label="Permalink to &quot;Verification levels&quot;">​</a></h2><p>Local tests, browser rendering, native compilation and physical-device receipt are separate results. The Android integration baseline is API 26+; a custom consumer must also supply its platform JSON runtime. Harmony SDK logic tests run offline and do not prove ArkTS compilation, camera release or trusted network receipt.</p><p>Capture/viewer and five read-only MCP tools exist. Exact host interoperability can be narrower than SDK tool coverage. Operational diagnosis remains unaccepted: the Codex gate is <code>UNSUPPORTED_SANDBOX</code>, and the direct Responses adapter has no accepted provider profile. Automatic repair (M4) is not implemented. Check <a href="./../reference/diagnosis">diagnosis status</a> before designing automation.</p>',9)])])}const h=e(o,[["render",d]]);export{u as __pageData,h as default};
